module Top;
    typedef struct { string name; int id; } alias_t;
    alias_t aliases[$], second, found[$];
    alias_t e;
    int r[$];
    initial begin
        e.name = "a"; e.id = 1; aliases.push_back(e);
        e.name = "b"; e.id = 3; aliases.push_back(e);
        e.name = "c"; e.id = 2; aliases.push_back(e);
        second = aliases[1];
        r = aliases.find_index with (item == second);
        $display("whole equality: size=%0d first=%0d", r.size(), r[0]);
        found = aliases.max with (item.id);
        $display("max by member: size=%0d id=%0d", found.size(), found[0].id);
    end
endmodule
